-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
-- P99 specifies seven warriors and one captain; remove three duplicated ProjectEQ warriors. Tools replace the ordinary scout with a personal fifteen-minute scout at the same position. Both accept rewards; only the original accepts tools. The alternate held bag appearance is not reproduced.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Emote("motions you to be silent.")
  end
end

function event_spawn(e)
  if e.self:GetNPCTypeID() == 120613 then
    eq.set_timer("despawn", 900000)
  end
end

function event_timer(e)
  if e.timer == "despawn" then
    eq.stop_timer("despawn")
    eq.depop()
  end
end

function event_trade(e)
  if e.self:GetNPCTypeID() == 120000 and item_lib.check_turn_in(e.trade, { item1 = 29683 }) then
    e.self:Say("Great! I was wondering when they would send someone out to give me these. In my haste and excitement of this new assignment I forgot these. This scout business is great I must say. It sure beats setting in Southern Ro studying the ruins. I've been following these Storm Giants for days. They've been wandering up and down the coast looking for something.")
    e.other:Faction(430, 8, 0)
    e.other:Faction(436, 2, 0)
    e.other:Faction(448, -4, 0)
    e.other:AddEXP(100000)
    eq.unique_spawn(120115, 0, 0, -3501, -4868, -108, 0)
    eq.spawn2(120121, 0, 0, -3507, -4897, -106, 0)
    eq.spawn2(120121, 0, 0, -3496, -4874, -109, 0)
    eq.spawn2(120121, 0, 0, -3474, -4863, -114, 0)
    eq.spawn2(120121, 0, 0, -3463, -4852, -117, 0)
    eq.spawn2(120121, 0, 0, -3452, -4841, -119, 0)
    eq.spawn2(120121, 0, 0, -3441, -4830, -122, 0)
    eq.spawn2(120121, 0, 0, -3430, -4819, -124, 0)
    eq.spawn2(120613, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading())
    eq.depop_with_timer()
  elseif item_lib.check_turn_in(e.trade, { item1 = 29684 }) then
    e.other:Faction(430, 25, 0)
    e.other:Faction(436, 6, 0)
    e.other:Faction(448, -12, 0)
    e.other:SummonItem(29688)
    e.other:SummonItem(29685)
    e.other:AddEXP(100000)
    e.self:Say("Ahhh the artifact, I will return this to Commander Leuz.  Please take this updated report to him ahead of me so he knows what to expect on my arrival.  Please accept this robe as a reward, I'm not very skilled at judging size so if you have a problem with wearing it please give it back and I will see what else I have for you.")
  elseif item_lib.check_turn_in(e.trade, { item1 = 29685 }) then
    e.other:SummonItem(29686)
    e.self:Say("Didn't like the robe, eh?  How about this then.  They packed it in my scout kit, and it is of no use to me, though it looks very nice.")
  elseif item_lib.check_turn_in(e.trade, { item1 = 29686 }) then
    e.other:SummonItem(29687)
    e.self:Say("Hmm, not the martial type, I take it.  Perhaps this will better suit your needs.")
  elseif item_lib.check_turn_in(e.trade, { item1 = 29687 }) then
    e.other:SummonItem(29685)
    e.self:Say("Right back where we started!  While this is an interesting game of dress-up, I have to resume my duties.  So, make up your mind!")
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
